import test from'node:test';import assert from'node:assert/strict';import{AutomataMesh,autoLingAutomaton,diseminerAutomaton,analogyAutomaton,iChingGrammarAutomaton,languageContactAutomaton,historicalMonteCarloAutomaton,autoNovelAutomaton,messyAutomaton,bootstrapKleinTools}from'../src/index.mjs';
test('AutoLing learns and applies one rule bidirectionally',async()=>{const a=autoLingAutomaton();await a.call({operation:'learn',rule:{id:'acts.v1',relation:'ACTS_ON',pattern:['$subject','$verb','$object'],template:'$subject $verb $object'}});assert.equal((await a.call({operation:'generate',relation:'ACTS_ON',args:['tool','transforms','state']})).surface,'tool transforms state');assert.deepEqual((await a.call({operation:'recognize',text:'tool transforms state'})).matches[0].structure,['tool','transforms','state']);});
test('DISEMINER learns incrementally and preserves source evidence',async()=>{const d=diseminerAutomaton();await d.call({operation:'ingest',text:'tool channel state tool',context:{source:'one'}});await d.call({operation:'ingest',text:'channel state expression',context:{source:'two'}});assert.ok((await d.call({operation:'neighbors',term:'tool'})).some(x=>x.term==='state'));const exported=await d.call({operation:'export'});assert.equal(exported.documents.length,2);assert.equal(exported.documents[0].source,'one');});
test('Klein analogy and I Ching grammar execute standalone',async()=>{const analogy=await analogyAutomaton().call({vocab:['a','b','c'],A:['a'],B:['b'],C:['c']});assert.deepEqual(analogy.result,['a','b','c']);const grammar=await iChingGrammarAutomaton().call({lines:[1,1,1,0,0,0]});assert.equal(grammar.lower.id,'creative');assert.equal(grammar.upper.id,'receptive');});
test('language contact and historical Monte Carlo are seeded and repeatable',async()=>{const l=languageContactAutomaton(),input={grammarA:{x:'a'},grammarB:{x:'b',y:'c'},contactRate:.5,generations:4,seed:9};assert.deepEqual(await l.call(input),await languageContactAutomaton().call(input));const m={variants:{a:1,b:2},generations:4,seed:3};assert.deepEqual(await historicalMonteCarloAutomaton().call(m),await historicalMonteCarloAutomaton().call(m));});
test('AutoNovel generates deterministically from registered primitives and combinators',async()=>{const a=autoNovelAutomaton();await a.call({operation:'register',domain:{id:'tools',primitives:[{id:'input'},{id:'transform'}],combinators:[{id:'compose.v1',type:'sequence',inputs:['input','transform'],output:'tool',apply:(x,y)=>`${x}->${y}`}]}});const result=await a.call({operation:'generate',spec:{domain:'tools',seeds:[{type:'input',value:'read'},{type:'transform',value:'summarize'}]}});assert.equal(result.ok,true);assert.equal(result.nodes.at(-1).value,'read->summarize');assert.deepEqual(result.lineage,['compose.v1']);});
test('MESSY simulates rules recursively without mutating initial agents',async()=>{const agents=[{id:'a',features:{value:0}}],rules=[{when:()=>true,apply:a=>({...a,features:{value:a.features.value+1}})}];const result=await messyAutomaton().call({agents,rules,ticks:3});assert.equal(result.finalState[0].features.value,3);assert.equal(agents[0].features.value,0);});
test('bootstrap installs actual Klein Automatons into the mesh',()=>{const mesh=new AutomataMesh(),tools=bootstrapKleinTools(mesh);assert.equal(tools.length,8);assert.deepEqual([...mesh.automatons.keys()].sort(),['autoling','autonovel','diseminer','historical-monte-carlo','iching-grammar','klein-analogy','language-contact','messy']);});
